mapper.select:
SELECT 
FROM t_payment_instrument_token
WHERE client_id = #{clientId} AND payment_intent_id = #{intentId}
  AND source_submission_id = #{sourceSubmissionId}

mapper.insert:
INSERT INTO t_payment_instrument_token ()
SELECT #{paymentInstrumentTokenId}, #{paymentInstrumentToken}, #{clientId}, #{paymentIntentId},
    #{sourceSubmissionId}, #{paymentMethodCode}, #{instrumentType,javaType=com.paytech.payment.execution.core.enums.InstrumentType,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR}, #{instrumentRef},
    #{expiresAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}, #{revokedAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}, #{createTime,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}, #{updateTime,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
FROM t_payment_intent
WHERE payment_intent_id = #{paymentIntentId} AND client_id = #{clientId}
  AND intent_status = 'OPEN' AND expires_at > UTC_TIMESTAMP(6)
  AND active_attempt_id IS NULL AND successful_attempt_id IS NULL
  AND #{expiresAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP} > UTC_TIMESTAMP(6) AND #{expiresAt,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP} <= expires_at
  AND NOT EXISTS (
      SELECT 1 FROM t_payment_attempt WHERE source_submission_id = #{sourceSubmissionId}
  )

mapper.select:
SELECT payment_instrument_token_id FROM t_payment_instrument_token
WHERE payment_instrument_token_id = #{paymentInstrumentTokenId}
  AND payment_instrument_token = #{paymentInstrumentToken}
  AND client_id = #{clientId} AND payment_intent_id = #{paymentIntentId}
  AND source_submission_id = #{sourceSubmissionId} AND payment_method_code = #{paymentMethodCode}
  AND instrument_type = #{instrumentType,javaType=com.paytech.payment.execution.core.enums.InstrumentType,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR} AND instrument_ref = #{instrumentRef}
  AND revoked_at IS NULL AND expires_at > UTC_TIMESTAMP(6)
FOR UPDATE
